// Deploys DPO2UTravelRuleGate on top of the existing registry, with the example target
// TravelRuleTransferLog. Lanes: attestation always; proof lanes when Groth16 verifiers are given
// (TRG_POLICY_VERIFIER / TRG_MEMBERSHIP_VERIFIER addresses) or deployed here (TRG_DEPLOY_VERIFIERS=
// policy,membership, from contracts/verifiers, generated by scripts/zk/export-verifiers.sh). A mock
// is never deployed. Verifiers are immutable in the gate, so adding a lane means a new gate.
// On the C-Chain mainnet, verifiers from a DEV setup (zk/setup.json) are refused: they need the
// multi-party ceremony first.
//   npx hardhat run scripts/deploy-travel-rule-gate.ts --network fuji
// Writes travelRuleGate { gate, target, useCase, ... } to deployments/<network>.json.
// Env: TRG_DEPLOY_VERIFIERS / TRG_POLICY_VERIFIER / TRG_MEMBERSHIP_VERIFIER (proof lanes, see above),
//      PRIVATE_KEY (deployer = gate admin), TRG_USE_CASE (default travel_rule_v1, the gateway set id; must be
//      configured and active in the registry by its admin before `execute` can pass),
//      TRG_PARTY_USE_CASE (optional: require both parties compliant under this use case),
//      TRG_OPERATOR (optional operator to authorize), ADMIN_ADDRESS (optional two-step transfer).
import { ethers, network } from "hardhat";
import fs from "node:fs";
import path from "node:path";

const id = (s: string) => ethers.keccak256(ethers.toUtf8Bytes(s));

async function main() {
  const [deployer] = await ethers.getSigners();
  const file = path.join(__dirname, "..", "deployments", `${network.name}.json`);
  const dep = JSON.parse(fs.readFileSync(file, "utf8"));
  if (!dep.registry) throw new Error(`no registry in ${file}`);
  const useCase = process.env.TRG_USE_CASE || "travel_rule_v1";
  const partyUseCase = process.env.TRG_PARTY_USE_CASE || "";
  console.log(`network=${network.name} deployer=${deployer.address} registry=${dep.registry} useCase=${useCase} partyUseCase=${partyUseCase || "(off)"}`);

  const setup = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "zk", "setup.json"), "utf8"));
  const deployList = (process.env.TRG_DEPLOY_VERIFIERS || "").split(",").map((s) => s.trim()).filter(Boolean);
  const verifiers: Record<string, { address: string; deployTx?: string; setup: string }> = {};
  for (const lane of ["policy", "membership"]) {
    const given = process.env[`TRG_${lane.toUpperCase()}_VERIFIER`];
    if (given) {
      if (!ethers.isAddress(given)) throw new Error(`TRG_${lane.toUpperCase()}_VERIFIER is not an address`);
      verifiers[lane] = { address: given, setup: "external" };
    } else if (deployList.includes(lane)) {
      if (!setup[lane]) throw new Error(`no ${lane} entry in zk/setup.json`);
      if (network.name === "avalanche" && setup[lane].setup !== "ceremony") throw new Error(`${lane} verifier comes from a ${setup[lane].setup} setup; mainnet needs the ceremony zkey (scripts/zk/export-verifiers.sh)`);
      const name = lane === "policy" ? "DPO2UPolicyGroth16Verifier" : "DPO2UMembershipGroth16Verifier";
      const v = await (await ethers.getContractFactory(name)).deploy();
      await v.waitForDeployment();
      verifiers[lane] = { address: await v.getAddress(), deployTx: v.deploymentTransaction()?.hash, setup: setup[lane].setup };
    }
  }
  const lanes = ["attestation", ...Object.keys(verifiers)].join(" + ");

  const target = await (await ethers.getContractFactory("TravelRuleTransferLog")).deploy();
  await target.waitForDeployment();
  const gate = await (await ethers.getContractFactory("DPO2UTravelRuleGate")).deploy(
    deployer.address,
    dep.registry,
    await target.getAddress(),
    id(useCase),
    partyUseCase ? id(partyUseCase) : ethers.ZeroHash,
    verifiers.policy?.address ?? ethers.ZeroAddress,
    verifiers.membership?.address ?? ethers.ZeroAddress,
  );
  await gate.waitForDeployment();
  const bindTx = await target.bindGate(await gate.getAddress());
  await bindTx.wait();

  const out: Record<string, unknown> = {
    gate: await gate.getAddress(),
    gateDeployTx: gate.deploymentTransaction()?.hash,
    target: await target.getAddress(),
    targetDeployTx: target.deploymentTransaction()?.hash,
    bindGateTx: bindTx.hash,
    useCase,
    useCaseId: id(useCase),
    partyUseCase: partyUseCase || null,
    lanes,
    verifiers,
    deployedAt: new Date().toISOString(),
  };
  if (process.env.TRG_OPERATOR) {
    const tx = await gate.authorizeOperator(process.env.TRG_OPERATOR, true);
    await tx.wait();
    out.operator = process.env.TRG_OPERATOR;
    out.operatorAuthTx = tx.hash;
  }
  if (process.env.ADMIN_ADDRESS) await (await gate.transferAdmin(process.env.ADMIN_ADDRESS)).wait();
  if (dep.travelRuleGate && dep.travelRuleGate.gate !== out.gate) {
    dep.previousTravelRuleGates = [...(dep.previousTravelRuleGates || []), dep.travelRuleGate];
  }
  dep.travelRuleGate = out;
  fs.writeFileSync(file, JSON.stringify(dep, null, 2) + "\n");
  console.log(out);
}

main().catch((e) => { console.error(e); process.exit(1); });
